// src/screens/HomeScreen.js - главный экран приложения
import React, { useState } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  ActivityIndicator,
  Alert,
  Image // ✅ ДОБАВЛЕНО
} from 'react-native';
import useApi from '../hooks/useApi';
import { apiService } from '../services/apiService';
import { Ionicons } from '@expo/vector-icons';

const API_URL = 'https://picsum.photos/v2/list?page=2&limit=4'; // 💡 URL для 4 случайных изображений

const HomeScreen = ({ navigation }) => {
  // ✅ API теперь загружает список картинок
  const { data: images, loading: apiLoading, error: apiError, refetch } = useApi(API_URL);

  const [localData, setLocalData] = useState([]);
  const [postLoading, setPostLoading] = useState(false);

  // ... (addLocalItem, createPost - остаются, но переименуем renderUser в renderImage)

  const renderImage = (image) => (
    <View key={image.id} style={styles.apiItem}>
      <Image 
        source={{ uri: image.download_url }} 
        style={styles.apiImage} 
        resizeMode="cover"
      />
      <Text style={styles.apiName}>Author: {image.author}</Text>
      <Text style={styles.apiEmail}>ID: {image.id}</Text>
    </View>
  );

  // ... (renderLocalItem, NavigationButton)

  return (
    <ScrollView style={styles.container}>

      {/* Секция API-данных */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Внешние API-Данные (Картинки)</Text>

        <TouchableOpacity 
          style={[styles.button, styles.apiButton]} 
          onPress={refetch}
          disabled={apiLoading}
        >
          <Text style={styles.navButtonText}>
            {apiLoading ? 'Загрузка...' : 'Обновить API-картинки (GET)'}
          </Text>
        </TouchableOpacity>

        {/* ... (остальной код POST-запроса) */}

        {apiError && <Text style={styles.errorText}>Ошибка: {apiError}</Text>}

        {(images && images.length > 0) && (
          <View style={styles.apiList}>
            <Text style={styles.listHeader}>Список загруженных картинок:</Text>
            {images.slice(0, 4).map(renderImage)} {/* Отображаем 4 картинки */}
          </View>
        )}
      </View>

      {/* ... (Секция Локальные данные и Навигация) */}
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  // ... (стили, добавьте стили для картинки)
  apiImage: {
    width: '100%',
    height: 100,
    borderRadius: 5,
    marginBottom: 5,
  },
  // ... (остальные стили)
});

export default HomeScreen;
